340	      .run(deviceId, metric, timestampMs, value);
341	  }
342	
343	  /**
344	   * Aggregate the samples of one device/metric inside the half-open window
345	   * [fromMs, toMs) into Unix-epoch aligned buckets of `bucketSeconds` width.
346	   * Empty buckets are omitted; rows come back in ascending bucket order. The
347	   * aggregation function is chosen by the caller from a fixed whitelist.
348	   */
349	  aggregateTelemetry({ deviceId, metric, fromMs, toMs, bucketSeconds, aggregate }) {
350	    const widthMs = bucketSeconds * 1000;
351	    let expression;
352	    switch (aggregate) {
353	      case "avg":
354	        expression = "AVG(value)";
355	        break;
356	      case "min":
357	        expression = "MIN(value)";
358	        break;
359	      case "max":
360	        expression = "MAX(value)";
361	        break;
362	      case "sum":
363	        expression = "SUM(value)";
364	        break;
365	      case "count":
366	        expression = "COUNT(*)";
367	        break;
368	      default:
369	        throw new Error(`unsupported telemetry aggregate ${aggregate}`);
370	    }
371	    return this.database
372	      .prepare(
373	        // Bucket start is floor(ts / width) * width, aligned to the Unix
374	        // epoch, including pre-1970 (negative) timestamps. Bound parameters
375	        // arrive as doubles, so `/` would be float division; `%` stays exact
376	        // at these magnitudes. The double-mod normalizes SQLite's truncated
377	        // remainder into a floored remainder in [0, width) for either sign.
378	        `SELECT ts - (((ts % ?) + ?) % ?) AS bucket, ${expression} AS value, COUNT(*) AS count
379	         FROM telemetry_samples
380	         WHERE device_id = ? AND metric = ? AND ts >= ? AND ts < ?
381	         GROUP BY bucket
382	         ORDER BY bucket ASC`,
383	      )
384	      .all(widthMs, widthMs, widthMs, deviceId, metric, fromMs, toMs)
385	      .map((row) => ({ startMs: row.bucket, value: row.value, count: row.count }));
386	  }
387	}
