127	      // stored in-flight copy always has retain clear even though the live
128	      // (possibly retained) delivery below keeps its real flag.
129	      this.store.insertMqttOutbound(this.id, { packetId, topic, payload, qos: 1, retain: false });
130	    }
131	    this.connection.send(mqtt.encodePublish({ topic, payload, qos: 1, packetId, retain }));
132	  }
133	
134	  #takePacketId() {
135	    for (let attempt = 0; attempt < 65535; attempt += 1) {
136	      const candidate = this.nextPacketId;
137	      this.nextPacketId = candidate === 65535 ? 1 : candidate + 1;
138	      if (!this.pendingPacketIds.has(candidate)) {
139	        this.pendingPacketIds.add(candidate);
140	        if (this.persistent) {
141	          this.store.setMqttNextPacketId(this.id, this.nextPacketId);
142	        }
143	        return candidate;
144	      }
145	    }
146	    throw new ProtocolError("no packet identifier is available for this session");
147	  }
