149	  /** A PUBACK removes just the one in-flight message it identifies. */
150	  acknowledge(packetId) {
151	    this.pendingPacketIds.delete(packetId);
152	    if (this.persistent) {
153	      this.store.deleteMqttOutbound(this.id, packetId);
154	    }
155	  }
