157	  /**
158	   * Resend after a reconnect: in-flight messages first, still carrying their
159	   * original packet ids with DUP set, then never-sent queued messages in
160	   * enqueue order with fresh packet ids and DUP clear.
161	   */
162	  replay() {
163	    if (!this.persistent || this.connection === null) {
164	      return;
165	    }
166	    const rows = this.store.listMqttOutbound(this.id);
167	    for (const row of rows.filter((entry) => entry.packetId !== null)) {
