169	        mqtt.encodePublish({ topic: row.topic, payload: row.payload, qos: 1, packetId: row.packetId, retain: row.retain, dup: true }),
170	      );
171	    }
172	    for (const row of rows.filter((entry) => entry.packetId === null)) {
173	      const packetId = this.#takePacketId();
174	      this.store.setMqttOutboundPacketId(row.seq, packetId);
175	      this.connection.send(
176	        mqtt.encodePublish({ topic: row.topic, payload: row.payload, qos: 1, packetId, retain: row.retain, dup: false }),
177	      );
