185	    this.socket = socket;
186	    this.buffer = Buffer.alloc(0);
187	    this.id = null;
188	    this.session = null;
189	    this.inboundPacketIds = new Set();
190	    this.keepAlive = 0;
191	    this.timer = null;
192	    this.will = null;
193	    this.graceful = false;
194	    this.closed = false;
195	    socket.setNoDelay(true);
196	    socket.on("data", (chunk) => this.#onData(chunk));
