304	
305	  #subscribe(body) {
306	    const subscribe = mqtt.decodeSubscribe(body);
307	    const returnCodes = [];
308	    for (const subscription of subscribe.subscriptions) {
309	      const granted = Math.min(subscription.qos, 1);
