392	export class Broker {
393	  constructor(service, options = {}) {
394	    this.service = service;
395	    this.store = service.store;
396	    this.host = options.host ?? "127.0.0.1";
397	    this.port = options.port ?? 1883;
398	    this.maxPacketBytes = options.maxPacketBytes ?? DEFAULT_MAX_PACKET_BYTES;
399	    this.connections = new Set();
400	    this.sessions = new Map();
401	    for (const clientId of this.store.listMqttSessionIds()) {
402	      this.sessions.set(clientId, new Session(this, clientId, true));
403	    }
404	    this.server = net.createServer((socket) => {
405	      this.connections.add(new ClientConnection(this, socket));
406	    });
407	  }
408	
409	  listen() {
410	    return new Promise((resolve, reject) => {
411	      this.server.once("error", reject);
412	      this.server.listen(this.port, this.host, () => {
413	        this.port = this.server.address().port;
414	        resolve({ host: this.host, port: this.port });
415	      });
416	    });
417	  }
418	
419	  close() {
420	    for (const connection of this.connections) {
421	      connection.destroy(true);
422	    }
423	    return new Promise((resolve) => this.server.close(() => resolve()));
424	  }
425	
426	  hasClient(clientId) {
427	    for (const connection of this.connections) {
428	      if (connection.id === clientId) {
429	        return true;
430	      }
431	    }
432	    return false;
433	  }
434	
435	  unregister(connection) {
436	    this.connections.delete(connection);
437	  }
438	
439	  createSession(clientId, persistent) {
440	    if (persistent) {
441	      this.store.createMqttSession(clientId);
442	    }
443	    const session = new Session(this, clientId, persistent);
444	    this.sessions.set(clientId, session);
445	    return session;
446	  }
447	
448	  /** Drop a persisted session (used when a clean session=1 connect succeeds). */
449	  discardSession(clientId) {
450	    if (this.sessions.delete(clientId)) {
451	      this.store.deleteMqttSession(clientId);
452	    }
453	  }
454	
455	  get clientIds() {
456	    return [...this.connections].filter((connection) => connection.id !== null).map((connection) => connection.id).sort();
457	  }
458	
459	  /**
460	   * Route one publication: retain it, fan it out to matching subscriptions and
461	   * then let the service evaluate mqtt rules. An empty retained payload clears
462	   * the retained message for that topic. Online connections receive real-time
463	   * fan-out; offline persistent sessions queue effective QoS 1 messages.
464	   */
465	  publish(topic, payload, options = {}) {
466	    const { qos = 0, retain = false } = options;
467	    const body = Buffer.isBuffer(payload) ? payload : Buffer.from(String(payload), "utf8");
468	    mqtt.validateTopicName(topic);
469	    if (retain) {
470	      if (body.length === 0) {
471	        this.store.deleteRetained(topic);
472	      } else {
473	        this.store.putRetained(topic, body, qos);
474	      }
475	    }
476	    for (const connection of this.connections) {
477	      connection.deliver(topic, body, qos);
478	    }
479	    for (const session of this.sessions.values()) {
480	      if (session.connection === null) {
481	        session.deliver(topic, body, qos, false);
482	      }
483	    }
484	    this.service.handlePublish(topic, body);
485	  }
486	}
